import{_ as l,o as i,c as e,a2 as t}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/plugins.md","filePath":"zh/guides/plugins.md","lastUpdated":1781609185000}'),r={name:"zh/guides/plugins.md"};function s(o,a,n,h,d,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>插件是从超市安装的能力包，可以给机器人增加功能。一个插件可以暴露 MCP 资源、技能，或其它打包好的设置元数据，具体取决于它发布时包含了什么。</p><hr><h2 id="机器人插件管理" tabindex="-1">机器人插件管理 <a class="header-anchor" href="#机器人插件管理" aria-label="Permalink to &quot;机器人插件管理&quot;">​</a></h2><p>打开机器人 <strong>详情页</strong>，进入 <strong>Plugins</strong> tab，就能管理这个机器人已安装的插件。</p><p>这里可以：</p><ul><li>查看已安装插件状态</li><li>查看插件是否需要授权</li><li>检查插件暴露的资源</li><li>在需要时开始或完成授权</li><li>从机器人上卸载插件</li><li>清理插件状态，方便重新安装</li></ul><p>Plugins tab 展示的是机器人级插件状态。安装新的能力包仍然从超市开始。</p><hr><h2 id="插件和其它功能的关系" tabindex="-1">插件和其它功能的关系 <a class="header-anchor" href="#插件和其它功能的关系" aria-label="Permalink to &quot;插件和其它功能的关系&quot;">​</a></h2><ul><li><strong>超市</strong> 用来发现和安装精选能力包。</li><li><strong>技能</strong> 是可复用的 Markdown 行为模块，插件可以提供技能。</li><li><strong>MCP</strong> 连接外部工具和资源，插件可以打包 MCP 相关设置。</li></ul><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/zh/guides/supermarket.html">超市</a></li><li><a href="/zh/guides/skills.html">技能</a></li><li><a href="/zh/guides/mcp.html">MCP</a></li><li><a href="/zh/guides/bot.html">机器人</a></li></ul>',14)])])}const c=l(r,[["render",s]]);export{g as __pageData,c as default};
